/**
 * Catalog Module - Static JSON Data Version
 * 
 * This module provides functions to access catalog data from the static JSON export.
 * All data is loaded from the JSON file generated by the backend export.
 * 
 * Usage:
 *   Import functions from this module in your pages/components
 *   Use getStaticProps to fetch data at build time
 *   All data is static - perfect for SEO
 */

// Re-export everything from data module
export {
  // Types
  Product,
  ProductVariant,
  ProductImage,
  ProductCategory,
  Category,
  CatalogMeta,
  CatalogData,
  
  // Main data functions
  getCatalogData,
  resetCache,
  
  // Product functions
  getProducts,
  getProductById,
  getProductBySlug,
  getProductsByCategoryId,
  getProductsByCategorySlug,
  searchProducts,
  getFeaturedProducts,
  getProductsOnSale,
  getProductsByBrand,
  getProductsInStock,
  getProductsOutOfStock,
  getLowestPricedProducts,
  getHighestPricedProducts,
  
  // Category functions
  getCategories,
  getCategoryById,
  getCategoryBySlug,
  getChildCategories,
  getParentCategory,
  getCategoryTree,
  
  // Utility functions
  getMeta,
  getAllBrands,
  getAllTags,
} from './data';

// Helper function to get catalog data for getStaticProps
export async function getStaticCatalogData() {
  // This is a simple wrapper for getStaticProps
  // In production, this will read from the JSON file
  const data = getCatalogData();
  return {
    products: data.products,
    categories: data.categories,
    meta: data.meta,
  };
}

// Helper for getStaticPaths - get all product IDs
export function getAllProductIds() {
  const products = getProducts();
  return products.map(p => ({ params: { id: String(p.id) } }));
}

// Helper for getStaticPaths - get all category slugs
export function getAllCategorySlugs() {
  const categories = getCategories();
  return categories.map(c => ({ params: { slug: c.slug } }));
}
